import hashlib


class RecordProgram:
    """Recomputes the record's checkable result."""

    def __init__(self):
        self.figures = {"failures_reviewed": 19, "fixes_released": 19, "lessons_shared": 19, "retest_tasks": 18}

    def run(self):
        total = sum(self.figures.values())
        return {"total": total,
                "digest": hashlib.sha256(str(total).encode()).hexdigest()}
